SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
 BEGIN TRANSACTION;
 IF EXISTS (SELECT 1 FROM [Store].[SchemaMigration] WHERE [MigrationKey]=N'010-account-commerce') BEGIN COMMIT; RETURN; END;
 IF SCHEMA_ID(N'Account') IS NULL EXEC(N'CREATE SCHEMA [Account]');
 CREATE TABLE [Account].[Profile](
  [Id] BIGINT IDENTITY(1,1) NOT NULL,[Email] NVARCHAR(254) NOT NULL,[FirstName] NVARCHAR(100) NOT NULL CONSTRAINT [DF_Account_Profile_FirstName] DEFAULT(N''),[LastName] NVARCHAR(100) NOT NULL CONSTRAINT [DF_Account_Profile_LastName] DEFAULT(N''),[Phone] NVARCHAR(30) NULL,[CreatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_Profile_CreatedAtUtc] DEFAULT SYSUTCDATETIME(),[UpdatedAtUtc] DATETIME2(3) NULL,
  CONSTRAINT [PK_Account_Profile] PRIMARY KEY([Id]),CONSTRAINT [UQ_Account_Profile_Email] UNIQUE([Email]));
 CREATE TABLE [Account].[Cart]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdProfile] BIGINT NOT NULL,[UpdatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_Cart_UpdatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_Cart] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_Cart_Profile] FOREIGN KEY([IdProfile]) REFERENCES [Account].[Profile]([Id]),CONSTRAINT [UQ_Account_Cart_Profile] UNIQUE([IdProfile]));
 CREATE TABLE [Account].[CartItem]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdCart] BIGINT NOT NULL,[IdProduct] BIGINT NOT NULL,[SalesPlanKey] NVARCHAR(64) NOT NULL,[Quantity] INT NOT NULL,[OptionsJson] NVARCHAR(MAX) NOT NULL CONSTRAINT [DF_Account_CartItem_OptionsJson] DEFAULT(N'{}'),[UpdatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_CartItem_UpdatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_CartItem] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_CartItem_Cart] FOREIGN KEY([IdCart]) REFERENCES [Account].[Cart]([Id]) ON DELETE CASCADE,CONSTRAINT [FK_Account_CartItem_Product] FOREIGN KEY([IdProduct]) REFERENCES [Store].[Product]([Id]),CONSTRAINT [UQ_Account_CartItem_Configuration] UNIQUE([IdCart],[IdProduct],[SalesPlanKey]),CONSTRAINT [CK_Account_CartItem_Quantity] CHECK([Quantity] BETWEEN 1 AND 99),CONSTRAINT [CK_Account_CartItem_Options] CHECK(ISJSON([OptionsJson])=1));
 CREATE TABLE [Account].[Favorite]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdProfile] BIGINT NOT NULL,[IdProduct] BIGINT NOT NULL,[CreatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_Favorite_CreatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_Favorite] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_Favorite_Profile] FOREIGN KEY([IdProfile]) REFERENCES [Account].[Profile]([Id]) ON DELETE CASCADE,CONSTRAINT [FK_Account_Favorite_Product] FOREIGN KEY([IdProduct]) REFERENCES [Store].[Product]([Id]),CONSTRAINT [UQ_Account_Favorite_Profile_Product] UNIQUE([IdProfile],[IdProduct]));
 CREATE TABLE [Account].[CompareItem]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdProfile] BIGINT NOT NULL,[IdProduct] BIGINT NOT NULL,[CreatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_CompareItem_CreatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_CompareItem] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_CompareItem_Profile] FOREIGN KEY([IdProfile]) REFERENCES [Account].[Profile]([Id]) ON DELETE CASCADE,CONSTRAINT [FK_Account_CompareItem_Product] FOREIGN KEY([IdProduct]) REFERENCES [Store].[Product]([Id]),CONSTRAINT [UQ_Account_CompareItem_Profile_Product] UNIQUE([IdProfile],[IdProduct]));
 CREATE TABLE [Account].[Address]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdProfile] BIGINT NOT NULL,[Title] NVARCHAR(100) NOT NULL,[Recipient] NVARCHAR(150) NOT NULL,[Phone] NVARCHAR(30) NOT NULL,[Country] NVARCHAR(100) NOT NULL,[CountryId] NVARCHAR(30) NOT NULL,[Province] NVARCHAR(100) NOT NULL,[ProvinceId] NVARCHAR(30) NOT NULL,[City] NVARCHAR(100) NOT NULL,[CityId] NVARCHAR(30) NOT NULL,[Street] NVARCHAR(500) NOT NULL,[PostalCode] NVARCHAR(20) NOT NULL,[IsDefault] BIT NOT NULL CONSTRAINT [DF_Account_Address_IsDefault] DEFAULT(0),[CreatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_Address_CreatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_Address] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_Address_Profile] FOREIGN KEY([IdProfile]) REFERENCES [Account].[Profile]([Id]) ON DELETE CASCADE);
 CREATE TABLE [Account].[CheckoutPreference]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdProfile] BIGINT NOT NULL,[IdSelectedAddress] BIGINT NULL,[PaymentMethod] NVARCHAR(40) NOT NULL CONSTRAINT [DF_Account_CheckoutPreference_PaymentMethod] DEFAULT(N'zarinpal'),[UpdatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_CheckoutPreference_UpdatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_CheckoutPreference] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_CheckoutPreference_Profile] FOREIGN KEY([IdProfile]) REFERENCES [Account].[Profile]([Id]) ON DELETE CASCADE,CONSTRAINT [FK_Account_CheckoutPreference_Address] FOREIGN KEY([IdSelectedAddress]) REFERENCES [Account].[Address]([Id]),CONSTRAINT [UQ_Account_CheckoutPreference_Profile] UNIQUE([IdProfile]));
 CREATE TABLE [Account].[ArticleInteraction]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdProfile] BIGINT NOT NULL,[ArticleSlug] NVARCHAR(160) NOT NULL,[InteractionType] NVARCHAR(20) NOT NULL,[CreatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_ArticleInteraction_CreatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_ArticleInteraction] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_ArticleInteraction_Profile] FOREIGN KEY([IdProfile]) REFERENCES [Account].[Profile]([Id]) ON DELETE CASCADE,CONSTRAINT [UQ_Account_ArticleInteraction] UNIQUE([IdProfile],[ArticleSlug],[InteractionType]),CONSTRAINT [CK_Account_ArticleInteraction_Type] CHECK([InteractionType] IN(N'like',N'bookmark',N'read')));
 CREATE TABLE [Account].[CustomerOrder]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdProfile] BIGINT NOT NULL,[IdAddress] BIGINT NULL,[OrderNumber] NVARCHAR(32) NOT NULL,[Status] NVARCHAR(30) NOT NULL CONSTRAINT [DF_Account_CustomerOrder_Status] DEFAULT(N'pending-payment'),[PaymentMethod] NVARCHAR(40) NOT NULL,[ItemCount] INT NOT NULL,[TotalAmount] DECIMAL(19,0) NOT NULL,[OrderedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_CustomerOrder_OrderedAtUtc] DEFAULT SYSUTCDATETIME(),[AddressSnapshotJson] NVARCHAR(MAX) NOT NULL,[CreatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_CustomerOrder_CreatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_CustomerOrder] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_CustomerOrder_Profile] FOREIGN KEY([IdProfile]) REFERENCES [Account].[Profile]([Id]),CONSTRAINT [FK_Account_CustomerOrder_Address] FOREIGN KEY([IdAddress]) REFERENCES [Account].[Address]([Id]),CONSTRAINT [UQ_Account_CustomerOrder_Number] UNIQUE([OrderNumber]),CONSTRAINT [CK_Account_CustomerOrder_Snapshot] CHECK(ISJSON([AddressSnapshotJson])=1));
 CREATE TABLE [Account].[CustomerOrderItem]([Id] BIGINT IDENTITY(1,1) NOT NULL,[IdCustomerOrder] BIGINT NOT NULL,[IdProduct] BIGINT NOT NULL,[ProductNameSnapshot] NVARCHAR(300) NOT NULL,[SalesPlanKey] NVARCHAR(64) NOT NULL,[Quantity] INT NOT NULL,[UnitAmount] DECIMAL(19,0) NOT NULL,[OptionsJson] NVARCHAR(MAX) NOT NULL,[CreatedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Account_CustomerOrderItem_CreatedAtUtc] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_Account_CustomerOrderItem] PRIMARY KEY([Id]),CONSTRAINT [FK_Account_CustomerOrderItem_Order] FOREIGN KEY([IdCustomerOrder]) REFERENCES [Account].[CustomerOrder]([Id]) ON DELETE CASCADE,CONSTRAINT [FK_Account_CustomerOrderItem_Product] FOREIGN KEY([IdProduct]) REFERENCES [Store].[Product]([Id]),CONSTRAINT [CK_Account_CustomerOrderItem_Quantity] CHECK([Quantity]>0),CONSTRAINT [CK_Account_CustomerOrderItem_Options] CHECK(ISJSON([OptionsJson])=1));
 INSERT INTO [Store].[SchemaMigration]([MigrationKey]) VALUES(N'010-account-commerce');
 COMMIT;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
